import type { ListeningItem, McqExercise, Speaker } from "./types";

type Q = [string, string[], number, string];
type Line = [number, string, string];

interface Def extends Omit<ListeningItem, "questions" | "lines"> {
  lines: Line[];
  questions: Q[];
}

function item(d: Def): ListeningItem {
  return {
    ...d,
    lines: d.lines.map(([s, en, fr]) => ({ s, en, fr })),
    questions: d.questions.map(
      ([prompt, options, answer, explanation], i): McqExercise => ({ id: `${d.id}-q${i + 1}`, kind: "mcq", prompt, options, answer, explanation }),
    ),
  };
}

const sp = (name: string, accent: Speaker["accent"], voice: Speaker["voice"]): Speaker => ({ name, accent, voice });

